WITH ranked AS (SELECT * FROM employees QUALIFY ROW_NUMBER() OVER (PARTITION BY manager_id ORDER BY hire_date DESC, id) = 1), enriched AS (SELECT *, RANK() OVER (PARTITION BY dept_id, level ORDER BY salary DESC) AS salary_rank, STDDEV_SAMP(salary) OVER (PARTITION BY dept_id) AS dept_id_stddev_samp_salary, FIRST_VALUE(level, TRUE) OVER (ORDER BY salary, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_level, LEAD(salary, 1) OVER (PARTITION BY dept_id, job_title ORDER BY salary, id) AS next_salary FROM ranked), enriched_employees AS (SELECT *, NTILE(4) OVER (PARTITION BY dept_id ORDER BY salary, id) AS salary_bucket, PERCENT_RANK() OVER (PARTITION BY level, manager_id ORDER BY dept_id_stddev_samp_salary DESC) AS dept_id_stddev_samp_salary_percent_rank FROM enriched), deduped AS (SELECT * FROM enriched_employees QUALIFY RANK() OVER (PARTITION BY manager_id ORDER BY dept_id_stddev_samp_salary_percent_rank NULLS FIRST) = 1), latest AS (SELECT * FROM deduped QUALIFY ROW_NUMBER() OVER (PARTITION BY manager_id ORDER BY dept_id_stddev_samp_salary DESC NULLS LAST, id) = 1), enriched_employees_2 AS (SELECT *, SUM(salary_bucket) OVER (PARTITION BY job_title ORDER BY salary_rank, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_salary_bucket, SUM(dept_id_stddev_samp_salary) OVER (PARTITION BY level ORDER BY hire_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_dept_id_stddev_samp_salary, MAX(salary_rank) OVER (PARTITION BY level) AS level_max_salary_rank FROM latest), scored AS (SELECT *, NTILE(5) OVER (PARTITION BY level ORDER BY salary DESC, id) AS salary_bucket_2, CUME_DIST() OVER (ORDER BY running_dept_id_stddev_samp_salary DESC NULLS LAST) AS running_dept_id_stddev_samp_salary_cume_dist FROM enriched_employees_2) SELECT * FROM (SELECT id, manager_id, running_dept_id_stddev_samp_salary_cume_dist, dept_id_stddev_samp_salary_percent_rank, next_salary FROM scored) src UNPIVOT (value FOR metric_name IN (running_dept_id_stddev_samp_salary_cume_dist AS RUNNING_DEPT_ID_STDDEV_SAMP_SALARY_CUME_DIST_VAL, dept_id_stddev_samp_salary_percent_rank AS DEPT_ID_STDDEV_SAMP_SALARY_PERCENT_RANK_VAL, next_salary AS NEXT_SALARY_VAL));
